foreach ($a in $archivos) {
    $destino = Join-Path $raiz $a.ruta
    $carpeta = Split-Path -Parent $destino
    if (-not (Test-Path $carpeta)) { New-Item -ItemType Directory -Path $carpeta -Force | Out-Null }
    [IO.File]::WriteAllBytes($destino, [Convert]::FromBase64String(($a.b64 -replace '\s','')))
    Write-Host ("  OK  " + $a.ruta) -ForegroundColor Green
}

function Buscar($n) {
    $p = Get-Command $n -ErrorAction SilentlyContinue
    if ($p) { return $p.Source }
    foreach ($r in @("C:\Program Files\PostgreSQL","C:\Program Files (x86)\PostgreSQL")) {
        if (-not (Test-Path $r)) { continue }
        foreach ($v in (Get-ChildItem $r -Directory -EA SilentlyContinue |
            Sort-Object { if ($_.Name -match '^(\d+)') { [int]$Matches[1] } else { 0 } } -Descending)) {
            $ruta = Join-Path $v.FullName "bin\$n.exe"
            if (Test-Path $ruta) { return $ruta }
        }
    }
    return $null
}
$PSQL = Buscar "psql"
$env:PGPASSWORD = "vigia"
$env:PGOPTIONS = "-c client_min_messages=warning"

Write-Host ""
Write-Host "=== Quien es el proveedor sin razon social ===" -ForegroundColor Cyan
$antes = $ErrorActionPreference
$ErrorActionPreference = "Continue"
if ($PSQL) { & $PSQL -h localhost -U vigia -d vigia -f "diagnostico-proveedor.sql" 2>&1 | Out-Host }
$ErrorActionPreference = $antes

Write-Host ""
Write-Host "=== Instalando las corridas programadas ===" -ForegroundColor Cyan
& "$raiz\instalar-tareas.ps1"

Write-Host ""
Write-Host "=== Resumen semanal de prueba, con datos de tu base ===" -ForegroundColor Cyan
& "$raiz\resumen-periodo.ps1" -Desde "2026-08-26" -Hasta "2026-09-02" -Titulo "Resumen semanal" -Salida "resumen-semanal.html"
if (Test-Path (Join-Path $raiz "resumen-semanal.html")) {
    Start-Process (Join-Path $raiz "resumen-semanal.html")
}
try { Stop-Transcript | Out-Null } catch { }
Start-Sleep -Seconds 2
